func (this *TableTab) SetWidgetSortIndicator() {
	var columns []*swt.TableColumn = this.table1.GetColumns()
	if this.sortIndicatorButton.GetSelection() {
		this.table1.SetSortDirection(swt.DOWN)
		for i := int32(0); i < int32(len(columns)); i++ {
			var column *swt.TableColumn = columns[i]
			if i == 0 {
				this.table1.SetSortColumn(column)
			}
			var listener swt.SelectionListener = swt.SelectionListenerWidgetSelectedAdapter(func(e *swt.SelectionEvent) {
				var sortDirection int32 = swt.DOWN
				if e.Widget == upcastswtTableColumnToswtWidget(this.table1.GetSortColumn()) {
					switch this.table1.GetSortDirection() {
					case swt.DOWN:
						sortDirection = swt.UP
						break
					case swt.UP:
						sortDirection = swt.NONE
						break
					}
				} else {
					this.table1.SetSortColumn(castswtWidgetToswtTableColumn(e.Widget))
				}
				this.table1.SetSortDirection(sortDirection)
			})
			column.AddSelectionListener(listener)
			column.SetDataKeyValue("SortListener", listener)
		}
	} else {
		this.table1.SetSortDirection(swt.NONE)
		for _, column := range columns {
			var listener swt.SelectionListener = column.GetDataKey("SortListener").(swt.SelectionListener)
			if listener != (nil) {
				column.RemoveSelectionListener(listener)
			}
		}
	}
}

