func (this *TableTab) specialPopupMenuItems_(menu *swt.Menu, event *swt.Event) {
	var item *swt.MenuItem = swt.NewMenuItem(menu, swt.PUSH)
	item.SetText("getItem(Point) on mouse coordinates")
	this.menuMouseCoords = this.table1.ToControl(event.X, event.Y)
	item.AddSelectionListener(swt.SelectionListenerWidgetSelectedAdapter(func(e *swt.SelectionEvent) {
		this.eventConsole.Append(fmt.Sprintf("getItem(Point(%v)) returned: %v", this.menuMouseCoords, this.table1.GetItemPoint(this.menuMouseCoords)))
		this.eventConsole.Append("\n")
	}))
}

func TableTabFindColumnContainingPoint(itemLike swt.TableItemLike, pointLike swt.PointLike) int32 {
	var item *swt.TableItem
	if itemLike != nil {
		item = itemLike.AsTableItem()
	}
	_ = item
	var point *swt.Point
	if pointLike != nil {
		point = pointLike.AsPoint()
	}
	_ = point
	for i := int32(0); i < item.GetParent().GetColumnCount(); i++ {
		var rect *swt.Rectangle = item.GetBoundsIndex(i)
		if rect.ContainsPt(point) {
			return i
		}
	}
	return -1
}

